/* GSA LIFE · browser UI */
(() => {
'use strict';
const E=window.GSAEngine, KEY='gsa-life-v1';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={home:'M3 10 12 3l9 7v10H3z M9 20v-7h6v7',book:'M3 4h7l2 2 2-2h7v15h-7l-2 2-2-2H3z M12 6v15',people:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M9 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8 M17 4a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.87',journal:'M5 3h14v18H5z M8 8h8 M8 12h8 M8 16h5',cap:'m2 9 10-5 10 5-10 5z M6 11v6q6 5 12 0v-6 M22 9v8',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z',ball:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M3 12h18 M12 3v18 M5.6 5.6q12 1 12.8 12.8 M5.6 18.4q1-12 12.8-12.8',flask:'M9 3h6 M10 3v7L4 20h16l-6-10V3 M7 15h10',heart:'M20.8 4.6a5.5 5.5 0 0 0-7.8 0L12 5.7l-1.1-1.1a5.5 5.5 0 0 0-7.8 7.8L12 21l8.8-8.6a5.5 5.5 0 0 0 0-7.8',moon:'M21 13a9 9 0 0 1-10-10A9 9 0 1 0 21 13',flag:'M5 21V3q4-2 8 0t8 0v10q-4 2-8 0t-8 0',refresh:'M20 7V2 M20 7h-5 M20 7a9 9 0 1 0 1 9',arrow:'M4 12h16 m-6-6 6 6-6 6',check:'m4 12 5 5L20 6',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0 M12 7v5l3 2'};
function icon(k){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[k]||paths.spark}"/></svg>`}
const campus=`<svg class="campus" viewBox="0 0 600 270" fill="none" aria-hidden="true"><circle cx="478" cy="62" r="30" fill="#f9e6ab"/><path d="M0 180 120 79 220 157 335 58 490 159 570 105 650 180v90H0Z" fill="#dbe6cf"/><path d="m0 213 140-83 126 76 119-75 156 82 59-10v67H0Z" fill="#cbdcbd"/><path d="M30 246h570v24H30z" fill="#bed0af"/><path d="m150 233 125-20 292 20-75 20-342 4z" fill="#aabc9a" opacity=".45"/><path d="M193 116h285v119H193z" fill="#f7f5e8"/><path d="M193 116h285v13H193z" fill="#95ad8b"/><path d="M193 163h285v6H193zM193 202h285v6H193z" fill="#e1e2d0"/><path d="M213 140h24v16h-24zM250 140h24v16h-24zM365 140h24v16h-24zM403 140h24v16h-24zM441 140h19v16h-19zM213 178h24v16h-24zM250 178h24v16h-24zM365 178h24v16h-24zM403 178h24v16h-24zM441 178h19v16h-19zM213 216h24v15h-24zM250 216h24v15h-24zM365 216h24v15h-24zM403 216h24v15h-24zM441 216h19v15h-19z" fill="#b3c8b2"/><path d="M287 98h67v139h-67z" fill="#e9ebdb"/><path d="M281 93h79v9h-79z" fill="#6e916f"/><path d="M304 202h33v35h-33z" fill="#789879"/><path d="M320 202v35" stroke="#c2d0b7" stroke-width="2"/><circle cx="320" cy="129" r="15" fill="#fafbf0" stroke="#a0b596" stroke-width="2"/><path d="M320 119v11l7 4" stroke="#789076" stroke-width="2"/><path d="M300 167h41v17h-41z" fill="#b3c8b2"/><path d="M100 244v-67M148 238v-66M509 240v-78M550 243v-52" stroke="#8c9e74" stroke-width="5"/><ellipse cx="100" cy="175" rx="25" ry="36" fill="#8eaf7e"/><ellipse cx="148" cy="166" rx="20" ry="30" fill="#a1bb8a"/><ellipse cx="509" cy="165" rx="24" ry="38" fill="#87a877"/><ellipse cx="550" cy="189" rx="19" ry="29" fill="#a3bd89"/><path d="M290 237h61l40 33H251z" fill="#e4e5ce"/><path d="M177 231v-36h-23" stroke="#96a789" stroke-width="3"/><path d="M145 188h17v13h-17z" fill="#e9ecdd" stroke="#96a789" stroke-width="2"/><path d="M150 202h9" stroke="#b38c62" stroke-width="2"/><circle cx="247" cy="239" r="4" fill="#637d65"/><path d="M247 245v10m0-7 5 3m-5 4-3 7m3-7 3 7" stroke="#637d65" stroke-width="3"/><circle cx="390" cy="242" r="4" fill="#b39f78"/><path d="M390 248v9m0-6 5 2m-5 4-3 7m3-7 3 7" stroke="#b39f78" stroke-width="3"/><path d="m414 73 5-3 5 3m-31 11 4-3 5 3" stroke="#a5b694" stroke-width="2"/></svg>`;
let state=null,draft=E.create('새로운 학생'),view='home',action='study',mode='normal',semesterNotice=null,toastTimer,storageOK=true;
try{const raw=localStorage.getItem(KEY);if(raw){const v=JSON.parse(raw);if([1,2,3].includes(v.version)&&v.state&&typeof v.state.turn==='number'&&v.state.stats&&Array.isArray(v.state.grades)){if(v.version<3&&!localStorage.getItem(KEY+'-v'+v.version+'-backup'))localStorage.setItem(KEY+'-v'+v.version+'-backup',raw);state=E.migrate(v.state);}}}catch(e){storageOK=false;}
function persist(){try{localStorage.setItem(KEY,JSON.stringify({version:3,state}));storageOK=true;}catch(e){storageOK=false;toast('저장 공간에 접근할 수 없어 이번 진행은 저장되지 않아요.');}}
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3800);}
function clubName(list,id){return list.find(x=>x.id===id)?.name||'미가입'}
function shell(body){const nav=[['home','home','학교생활'],['grades','book','성적표'],['clubs','people','동아리·학생회'],['journal','journal','나의 기록'],['future','cap','진학·졸업']];$('#app').innerHTML=`<aside class="sidebar"><div class="brand"><div class="brand-mark">g.</div><span>GSA LIFE</span></div><div class="brand-sub">THREE YEARS, YOUR STORY</div><div class="nav-label">MY SCHOOL LIFE</div><nav class="nav">${nav.map(([id,i,n])=>`<button data-nav="${id}" class="${view===id?'active':''}" ${!state&&id!=='home'?'disabled':''} ${view===id?'aria-current="page"':''}>${icon(i)}<span>${n}</span></button>`).join('')}</nav><div class="sidebar-bottom"><div class="side-note"><strong>정답이 없는 3년.</strong>어떤 학생으로 기억될지는<br>너의 선택에 달려 있어.</div><button class="new-btn" data-do="new">${icon('refresh')}<span>새로운 학교생활</span></button></div></aside><main class="layout"><header class="topbar"><div class="breadcrumb"><span class="welcome-small">GSA LIFE &nbsp; / &nbsp; </span>나의 캠퍼스 &nbsp; / &nbsp; <b>${nav.find(n=>n[0]===view)?.[2]||'입학하기'}</b></div><div class="top-right"><span class="save-status">${state?(storageOK?'이 브라우저에 자동 저장':'저장 사용 불가'):'나만의 3년을 시작해요'}</span><button class="new-mobile" data-do="new" aria-label="새로운 학교생활">↻</button><div class="avatar" aria-label="학생 프로필">${esc((state?.name||'G').slice(0,1))}</div></div></header>${body}<footer class="footer">GSA LIFE · 나의 광주과학고 3년 &nbsp; / &nbsp; 비공식 팬 시뮬레이터<br>학기당 8턴으로 압축한 비공식 게임입니다. 3학년 1학기 입시 일정, 수상 효과와 응급실·생존 판정은 게임 설정입니다.</footer></main>`;bind();}
function statCards(s,cls='stats-grid'){
 const items=[['intelligence','지능','spark','교과 학습과 개념 이해'],['social','사회성','people','관계와 면접 소통'],['athletics','운동','ball','운동부 테스트와 훈련'],['discipline','자기관리','book','학습 습관과 준비'],['luck','행운','spark','테스트·면접의 기회'],['creativity','창의성','flask','연구와 새로운 제안'],['resilience','회복력','heart','피로 회복과 건강 관리'],['leadership','리더십','flag','학생회와 기장 선발']];
 return `<div class="${cls}">${items.map(([k,l,i,d])=>`<div class="card stat" title="${d}"><div class="stat-top">${icon(i)}${l}</div><div class="stat-value">${Math.round(s[k])}<small>/ 100</small></div><div class="bar" role="meter" aria-label="${l}" aria-valuenow="${Math.round(s[k])}" aria-valuemin="0" aria-valuemax="100"><span style="width:${s[k]}%"></span></div></div>`).join('')}</div>`;
}
function typeCard(s){const t=E.archetypes.find(t=>t.id===s.archetype);return `<div class="type-card"><div><span class="eyebrow">MY CHARACTER TYPE</span><h3>${esc(t?.name||'나만의 성장형')}</h3><p>${esc(t?.description||'이전 학교생활을 이어가는 학생입니다. 쌓아온 성적과 활동은 그대로 유지됩니다.')}</p></div><span class="type-symbol">✦</span></div>`;}
function sportsNames(s){return s.sportsClubs.length?s.sportsClubs.map(id=>clubName(E.sportsClubs,id)).join(' · '):'운동부 미가입';}
function heading(k,t,d,tag='STORIES UPDATE · v0.3.1'){return `<div class="heading"><div><div class="eyebrow">${k}</div><h1>${t}</h1><p>${d}</p></div><span class="tag">${tag}</span></div>`}
function setup(){shell(`${heading('YOUR NEXT CHAPTER','각자의 강점, 새로운 시작.','어떤 유형으로 태어나도, 3년의 선택은 네 몫이야.')}<section class="hero"><div class="hero-copy"><div class="hero-kicker"><span class="badge-dark">GSA</span> 능력치도, 학교생활도 더 다양하게</div><h2>머리가 좋은 나.<br>친구가 많은 나. 운이 좋은 나.</h2><p>서로 다른 출발점과 여덟 가지 능력.<br>이번 3년은 어떤 이야기로 채워질까?</p></div>${campus}</section><div class="setup-columns"><section class="card setup-panel"><h2>나의 입학 카드</h2><p>유형에 따라 강점이 달라지고, 능력치는 범위 안에서 무작위로 정해져요.</p><div class="form-grid"><label class="field full">이름 또는 별명<input id="student-name" maxlength="16" placeholder="어떤 이름으로 기억될까?" autocomplete="off" value="${draft.name==='새로운 학생'?'':esc(draft.name)}"></label><label class="field">학술동아리<select id="academic-club">${E.academicClubs.map(c=>`<option value="${c.id}">${c.name}</option>`).join('')}</select><small>질문과 실험으로 탐구 경험을 쌓아요.</small></label><label class="field">일반 상설동아리<select id="activity-club">${E.activityClubs.map(c=>`<option value="${c.id}" ${c.id==='none'?'selected':''}>${c.name}</option>`).join('')}</select><small>운동부는 입학 후 별도 테스트로 선발해요.</small></label></div><div class="row" style="margin-top:26px"><strong style="font-size:12px">무작위로 만난 나</strong><button class="secondary" data-do="reroll">↻ 유형과 능력치 다시 뽑기</button></div>${typeCard(draft)}${statCards(draft.stats,'setup-stats')}<small style="font-size:10px">유형은 초기 강점이에요. 입학 후의 활동으로 다른 능력도 성장할 수 있어요.</small><button class="primary" data-do="start">입학하고 운동부 테스트 보기 ${icon('arrow')}</button></section><aside class="card setup-panel"><div class="eyebrow">NEW SCHOOL RULES</div><h2 style="margin-top:12px">이번 3년의 중요한 순간</h2>${[['01','1학년 첫 주 · 운동부 테스트','농구부와 축구부 중 한 곳에 지원해요. 운동 능력이 선발에 가장 크게 작용하고, 행운도 영향을 줍니다.'],['02','2학년 첫 주 · 두 번째 도전','아직 가입하지 않은 운동부에 지원할 수 있어요. 합격하면 두 운동부에서 함께 활동할 수도 있어요.'],['03','학생회와 기장 · 나의 역할','회장·부회장은 학생 공개질문에, 부서 임원은 면접에 응답해요. 기장은 1학년을 마칠 때 선출합니다.'],['04','진학과 졸업 · 서로 다른 관문','3학년 1학기에 대학 원서와 면접을 진행해요. TOEIC은 1학년부터 준비할 수 있고, 졸업 기준은 730점이에요.']].map(([n,t,d])=>`<div class="step-note"><span class="step-num">${n}</span><div><b>${t}</b><p>${d}</p></div></div>`).join('')}<div class="tip" style="margin-top:18px"><h3>한계에 닿기 전에 쉬어가기</h3><p>피로·스트레스 중 하나가 100 이상이거나 둘 다 90 이상이면 응급실 사건이 발생해요. 이 게임에는 생존과 사망으로 나뉘는 결말이 있습니다.</p></div></aside></div>`)}
function timeline(){const p=E.getPhase(state);return `<div class="timeline" aria-label="6학기 진행도">${Array.from({length:6},(_,i)=>`<div class="term ${i<Math.floor(state.turn/8)?'done':i===Math.floor(state.turn/8)?'current':''}"><span>${Math.floor(i/2)+1}학년 ${i%2+1}학기</span><small>${i<Math.floor(state.turn/8)?'완료':i===Math.floor(state.turn/8)?`${p.week} / 8주`:''}</small></div>`).join('')}</div>`}
function recentLog(limit=4){return state.log.slice(0,limit).map(l=>`<div class="journal-item"><small>${esc(l.label||(l.turn?`학교생활 ${l.turn}주차`:'입학 첫 주'))}</small><p>${esc(l.message||l.text||l)}</p></div>`).join('')||'<p style="font-size:11px;color:#8b977f">첫 번째 이야기를 기다리고 있어요.</p>'}
function profile(){const p=E.getProfile(state),type=E.archetypes.find(t=>t.id===state.archetype),d=E.getDormStatus(state);return `<section class="card profile"><div class="profile-head"><div class="avatar">${esc(state.name.slice(0,1))}</div><div><strong>${esc(state.name)}</strong><small>${esc(type?.name||'나만의 성장형')} · ${esc(p.rankLabel)}</small></div></div>${[['fatigue','피로도','fatigue'],['stress','스트레스','stress']].map(([k,l,c])=>`<div class="meter ${c} ${state.stats[k]>=90?'critical':''}"><div class="row"><span>${l}</span><b>${Math.round(state.stats[k])} <small>/ 한계 100</small></b></div><div class="bar threshold-bar"><span style="width:${Math.min(100,state.stats[k]/120*100)}%"></span><i></i></div></div>`).join('')}<div class="health-state ${state.illnessWeeks?'is-sick':''}"><strong>${state.illnessWeeks?`회복 중 · ${state.illnessWeeks}주`:'일상 생활 중'}</strong><span>피로·스트레스가 높다면 잠깐 쉬어가세요.</span></div><div class="dorm-status ${d.efficiency<1?'strained':''}"><strong>기숙사 · ${esc(d.label)}</strong><p>${esc(d.description)}</p><small>생활에 따른 학습 효율 ${Math.round(d.efficiency*100)}%</small></div><div class="profile-divider"></div><div class="metric"><span>누적 평점</span><strong class="gpa">${state.grades.length?p.gpa.toFixed(2):'—'} <small style="font-size:10px">/ 4.3</small></strong></div><div class="metric"><span>연구 역량</span><strong>${Math.round(state.stats.research)}</strong></div><div class="metric"><span>학생회</span><strong>${esc(state.councilRole||'일반 학생')}</strong></div>${state.captain?`<div class="metric"><span>기장</span><strong>${esc(state.captainClub||'동아리')}</strong></div>`:''}<div class="profile-divider"></div><div class="metric"><span>TOEIC 최고점</span><strong>${state.toeic.best||'미응시'}${state.toeic.best?'점':''}</strong></div><div class="toeic-mini ${state.toeic.best>=730?'passed':''}">${state.toeic.best>=730?'졸업 영어 기준 충족':'졸업 기준 730점 · 1학년부터 준비 · 2학년부터 응시'}</div><div class="club-pill">${icon('flask')}${esc(clubName(E.academicClubs,state.academicClub))}</div><div class="club-pill">${icon('people')}${esc(clubName(E.activityClubs,state.activityClub))}</div><div class="club-pill sports-pill">${icon('ball')}${esc(sportsNames(state))}</div></section>`;}
function actionLocked(a){return (a.id==='sports'&&!state.sportsClubs.length)||(a.id==='toeic'&&state.turn<16);}
function actionDescription(a){return a.id==='sports'&&!state.sportsClubs.length?'운동부 테스트에 합격하면 참여할 수 있어요.':a.id==='toeic'&&state.turn<16?'2학년부터 선택할 수 있어요.':a.description;}
function awardsPanel(){return `<section class="card awards-panel"><div class="section-title"><h2>도전의 기록</h2><small>경기와 탐구의 순간들</small></div>${state.awards.length?`<div class="award-grid">${state.awards.map(a=>`<div class="award-card"><span>${a.kind==='sports'?'◉':'✦'}</span><div><strong>${esc(a.name)}</strong><small>${a.year||Math.min(3,Math.floor((a.turn||0)/16)+1)}학년 · ${a.kind==='sports'?'교육감배':'올림피아드'}</small></div></div>`).join('')}</div>`:'<p class="section-description">아직 수상 기록이 없어요. 팀 훈련과 탐구를 이어가며 새로운 도전에 참여해보세요.</p>'}<div class="event-calendar"><span>1학기 후 · 교육감배 대표 선발</span><span>1·2학년 · 올림피아드 도전</span><span>1학년 말 · 기장 선출</span></div></section>`;}

function studyPlan(p){const enabled=p.availableStudyModes||['normal'];const options=[['normal','기본 자습','추가 피로 없음'],['night','심야 자습','시험 2주 전부터'],['dawn','새벽 자습','시험 1주 전부터'],['both','심야 + 새벽','준비와 피로 모두 ↑']];return `<section class="exam-box"><div class="row"><h3>${p.examName|| (p.week<=4?'중간고사':'기말고사')} · ${p.exam?'시험 주간':`${p.weeksToExam}주 전`}</h3><span class="tag">자습 일정</span></div><p>기본 수업·자습은 자동 진행됩니다. 추가 자습은 매주 선택하며, 시험 준비도와 피로가 함께 쌓여요.</p><div class="study-options">${options.map(([id,n,d])=>`<button data-mode="${id}" class="${mode===id?'active':''}" aria-pressed="${mode===id}" ${enabled.includes(id)?'':'disabled'}>${n}<small>${enabled.includes(id)?d:'아직 시작 전'}</small></button>`).join('')}</div><div class="study-note">${mode==='both'?'두 자습을 모두 선택했어요. 피로가 높은 상태라면 휴식도 고려해보세요.':mode==='night'?'심야자습으로 시험 준비도를 더 쌓아요. 피로도 함께 올라가요.':mode==='dawn'?'새벽자습으로 개념을 정리해요. 수면이 줄어 피로가 올라가요.':'오늘은 기본 자습을 하며 생활 리듬을 유지해요.'}</div></section>`;}
function actionInfo(a){if(a.id==='club'&&state.activityClub==='none')return {...a,name:'자율 활동',description:'내 시간을 확보하고 몸과 마음을 정돈해요.',effectsText:'피로 ↓ · 자기관리 ↑ · 스트레스 ↓'};return a;}
function home(){if(!state.alive||state.turn>=48){future();return;}const p=E.getPhase(state);if(!p.availableStudyModes.includes(mode))mode='normal';const termLabel=`${p.year}학년 ${p.semester}학기`;const tips=state.stats.fatigue>=80||state.stats.stress>=80?'몸과 마음이 한계에 가까워요. 지금은 휴식을 선택해 상태를 회복하는 게 좋아요.':E.getDormStatus(state).efficiency<1?'기숙사 생활이 편하지 않아 학습 효율이 떨어졌어요. 친구와 시간을 보내거나 대화의 기회를 선택해보세요.':state.illnessWeeks?'몸이 아픈 동안에는 학습과 활동 효율이 떨어져요. 충분히 쉬어 회복을 도와주세요.':state.stats.fatigue>60?'피로가 많이 쌓였어요. 추가 자습과 훈련을 줄이고 쉬어가면 질병 위험이 낮아져요.':state.stats.stress>65?'마음도 휴식이 필요해요. 친구와 시간을 보내거나 잠깐 쉬어도 괜찮아요.':p.nightAvailable?'시험 준비 기간이에요. 추가 자습은 준비도를 높이지만 피로가 쌓이므로 몸 상태도 살펴주세요.':'이번 주의 작은 선택이 쌓여 너의 이야기가 됩니다. 네 강점을 살리거나 새로운 능력을 키워보세요.';
shell(`${heading('MY SCHOOL LIFE',`${termLabel}, ${p.week}주차`,`${esc(state.name)}의 이번 주에는 어떤 일이 기다릴까?`,p.exam?'EXAM WEEK':p.nightAvailable?'STUDY SEASON':'STORIES UPDATE · v0.3.1')}${timeline()}<section class="hero"><div class="hero-copy"><div class="hero-kicker"><span class="badge-dark">${termLabel}</span> ${p.exam?'시험 주간':'각자의 강점으로 쓰는 학교생활'}</div><h2>${p.exam?'준비도 중요하지만,<br>몸의 신호도 들어봐.':state.turn<8?'서로 다른 시작,<br>나만의 자리를 찾는 중.':state.turn<32?'친구와 팀, 그리고<br>조금 더 넓어진 나.':'익숙해진 교정에서<br>다음 시작을 준비해.'}</h2><p>${esc(E.archetypes.find(t=>t.id===state.archetype)?.name||'나만의 성장형')} · ${esc(sportsNames(state))}<br>${esc(state.councilRole||'일반 학생')}</p></div>${campus}</section><div class="columns"><div><div class="section-title"><h2>여덟 가지 가능성</h2><small>초기 유형과 활동에 따라 성장해요</small></div>${statCards(state.stats)}${state.illnessWeeks?'<div class="notice illness-notice">현재 몸살로 활동 효율이 떨어진 상태예요. 휴식을 선택하면 회복에 도움이 됩니다.</div>':''}${studyPlan(p)}<div class="section-title"><h2>이번 주, 무엇을 할까?</h2><small>활동 1개를 선택하세요</small></div><div class="action-grid">${E.actions.map(actionInfo).map(a=>`<button class="action ${action===a.id?'selected':''}" data-action="${a.id}" aria-pressed="${action===a.id}" ${actionLocked(a)?'disabled':''}><div class="action-icon">${icon(({study:'book',train:'ball',sports:'ball',academic:'flask',club:'people',research:'flask',friends:'heart',rest:'moon',council:'flag',english:'book',toeic:'journal'})[a.id]||a.icon)}</div><span class="radio-dot"></span><div><h3>${esc(a.name)}</h3><p>${esc(actionDescription(a))}</p><div class="effect">${esc(a.effectsText)}</div></div></button>`).join('')}</div><button class="primary advance" data-do="advance"><span>${esc(actionInfo(E.actions.find(a=>a.id===action)||E.actions[0]).name)} · 한 주 보내기</span><span style="display:flex;align-items:center;gap:10px"><small>WEEK ${state.turn+1} / 48</small>${icon('arrow')}</span></button><p class="action-foot">추가 자습은 위에서 별도로 선택해요 · 진행은 이 브라우저에 자동 저장됩니다</p></div><aside class="right-column">${profile()}<div class="tip"><h3>✦ 이번 주의 작은 조언</h3><p>${tips}</p></div><section class="card journal"><h3>최근의 순간들</h3>${recentLog()}</section></aside></div>`);}

function grades(){const p=E.getProfile(state);shell(`${heading('ACADEMIC RECORD','숫자에 담긴 노력들.','학기가 끝날 때마다, 너의 성적표가 채워집니다.','TRANSCRIPT')}${timeline()}<div class="summary-cards"><div class="card summary-card"><small>누적 평점 / 4.3</small><strong>${state.grades.length?p.gpa.toFixed(2):'—'}</strong></div><div class="card summary-card"><small>이수 학점</small><strong>${p.credits}</strong></div><div class="card summary-card"><small>마친 학기</small><strong>${state.grades.length} <small>/ 6</small></strong></div></div><div class="notice">학점은 과목별 단위 수, 평점은 성취도를 나타내요. 누적 평점은 F를 포함한 수강 학점을 가중치로 계산합니다. 게임용 4.3점 체계입니다.</div>${state.grades.length?state.grades.map(g=>`<details class="card details" open><summary><strong>${g.year}학년 ${g.semester}학기</strong><span>평점 ${g.gpa.toFixed(2)} · ${g.earnedCredits ?? g.credits}학점 이수</span></summary><div class="table-wrap"><table><thead><tr><th>과목</th><th>과목 학점</th><th>성취 점수</th><th>등급</th><th>평점</th></tr></thead><tbody>${g.subjects.map(s=>`<tr><td>${esc(s.name)}</td><td>${s.credits}</td><td>${s.score.toFixed(1)}</td><td>${esc(s.grade)}</td><td>${s.point.toFixed(1)}</td></tr>`).join('')}</tbody></table></div></details>`).join(''):`<div class="card empty">아직 완성된 성적표가 없어요.<br>1학년 1학기 8주차를 마치면 첫 성적을 확인할 수 있어요.</div>`}<div class="section-title" style="margin-top:25px"><h2>이번 학기 수강 과목</h2></div><div class="notice">${E.getSubjects(state).map(s=>`${esc(s.name)} (${s.credits}학점)`).join(' · ')}<br>선택과목은 2학년 2학기 시작에 2개를 고릅니다.</div>`)}
function clubs(){shell(`${heading('BEYOND THE CLASSROOM','함께하는 곳, 성장하는 나.','운동장과 연구실, 기숙사에서 이어지는 너의 이야기.','CLUBS & COUNCIL')}<section class="card membership-section"><div class="section-title"><h2>나의 운동부</h2><span class="tag">최대 2개 소속</span></div><div class="sports-grid">${E.sportsClubs.map(c=>`<div class="sports-card ${state.sportsClubs.includes(c.id)?'joined':''}"><div class="row"><h3>${c.id==='basketball'?'◉':'⚽'} ${esc(c.name)}</h3><span class="tag">${state.sportsClubs.includes(c.id)?'선발 완료':'미가입'}</span></div><p>${esc(c.description)}</p><small>${state.sportsClubs.includes(c.id)?'운동부 훈련으로 활동 경험을 쌓을 수 있어요.':'첫 주 테스트 또는 2학년 추가 모집에서 지원해요.'}</small></div>`).join('')}</div><p class="section-description">꾸준한 훈련과 실력으로 팀 안의 입지를 쌓아요. 매년 1학기가 끝나면 교육감배 대표에 도전할 수 있어요.</p><details class="mini-details"><summary>운동부 테스트 기록 (${state.sportsTryouts.length})</summary>${state.sportsTryouts.length?state.sportsTryouts.map(t=>`<div class="history-line"><span>${t.year}학년 · ${t.clubId?esc(clubName(E.sportsClubs,t.clubId)):'추가 지원 안 함'}</span><b>${!t.clubId?'미응시':t.passed?'합격':'불합격'}</b></div>`).join(''):'<p>아직 테스트 기록이 없어요.</p>'}</details></section><section class="card membership-section"><div class="section-title"><h2>학생회 · 2학기 모집</h2><span class="tag">현재: ${esc(state.councilRole)}</span></div><div class="council-years"><div><small>1학년 2학기</small><strong>학생회 부회장 / 각 부서 차장</strong></div><div><small>2학년 2학기</small><strong>학생회 회장 / 각 부서 부장</strong></div></div><p class="section-description">회장·부회장: 학생들의 공개질문에 답하고 투표 결과를 기다려요.<br>각 부서 차장·부장: 부서 업무에 관한 면접을 진행해요.</p><div class="department-grid">${E.departments.map(d=>`<span>${esc(d.name)}</span>`).join('')}</div><details class="mini-details"><summary>나의 학생회 지원 기록 (${state.councilHistory.length})</summary>${state.councilHistory.length?state.councilHistory.map(h=>`<div class="history-line"><span>${h.year}학년 · ${esc(h.role)}</span><b>${h.role==='지원하지 않음'?'미지원':h.passed?'선발':'미선발'}</b></div>`).join(''):'<p>아직 지원 기록이 없어요. 1·2학년의 2학기에 지원할 수 있어요.</p>'}</details></section>${awardsPanel()}<div class="club-grid"><section class="card club-card"><div class="eyebrow">ACADEMIC CLUB</div><h3 style="margin-top:12px">${esc(clubName(E.academicClubs,state.academicClub))}</h3><p>친구들과 함께 질문하고 탐구해요. 전공 이해와 연구 경험을 쌓을 수 있어요.</p><span class="tag">연구 역량 ${Math.round(state.stats.research)} / 100</span></section><section class="card club-card"><div class="eyebrow">AFTER SCHOOL</div><h3 style="margin-top:12px">${esc(clubName(E.activityClubs,state.activityClub))}</h3><p>운동부와 별도로 선택한 일반 상설동아리예요. 자율 활동을 골랐다면 내 시간을 확보할 수 있어요.</p><span class="tag">${state.captain?`${esc(state.captainClub||'동아리')} 기장`:'1학년을 마칠 때 기장 선출'}</span></section><section class="card club-card"><div class="eyebrow">MY DIRECTION</div><h3 style="margin-top:12px">나의 선택과목</h3><p>${state.electives.length?state.electives.map(id=>esc(clubName(E.electives,id))).join(' · '):'2학년 2학기부터 관심 분야의 과목 2개를 선택해요.'}</p></section><section class="card club-card"><div class="eyebrow">MY CHARACTER</div><h3 style="margin-top:12px">${esc(E.archetypes.find(t=>t.id===state.archetype)?.name||'나만의 성장형')}</h3><p>${esc(E.archetypes.find(t=>t.id===state.archetype)?.description||'이전의 학교생활을 이어가는 나만의 유형이에요.')}</p></section></div>`)}
function journal(){shell(`${heading('LITTLE MOMENTS','그때, 우리는.','작은 선택들이 모여 하나의 학교생활이 됩니다.','MY JOURNAL')}<div class="card journal log-full">${recentLog(999)}</div>`)}
function applicationForm(){return `<div class="university-grid">${E.universities.map(u=>`<label class="university"><input name="university" type="checkbox" value="${u.id}">${esc(u.name)}<p>${esc(u.description)}</p></label>`).join('')}</div><button class="primary" data-do="apply" style="margin-top:20px">선택한 대학에 원서 제출 ${icon('arrow')}</button><p class="form-hint">1~3곳을 선택하세요. 제출한 지원 대학은 변경할 수 없어요.</p>`;}
function applicationNames(){return (state.applications||[]).map(u=>typeof u==='string'?clubName(E.universities,u):u.name||clubName(E.universities,u.id)).join(' · ');}
function toeicPanel(){const t=state.toeic,passed=t.best>=730;return `<section class="card toeic-panel"><div class="row"><div><div class="eyebrow">GRADUATION REQUIREMENT</div><h2>TOEIC · 졸업을 위한 한 걸음</h2></div><span class="tag">${passed?'기준 충족':'730점 필요'}</span></div><div class="toeic-score"><strong>${t.best||'—'}</strong><span>/ 990점</span><span class="goal">목표 730점</span></div><div class="toeic-progress"><span style="width:${t.best/990*100}%"></span><i style="left:${730/990*100}%"></i></div><p>${passed?'졸업 영어 기준을 충족했어요.':state.turn<16?'지금부터 주간 활동에서 TOEIC 준비를 선택할 수 있어요. 응시는 2학년부터 가능해요.':'TOEIC 준비로 실력을 쌓고 응시해보세요. 지능과 행운도 점수에 영향을 줘요.'}</p>${state.turn>=48&&state.alive&&!passed?`<div class="retake-actions"><button class="secondary" data-do="prepare-toeic">한 주 더 준비하기</button><button class="primary" data-do="retake-toeic">${t.attempts.length?'TOEIC 다시 응시하기':'TOEIC 응시하기'}</button></div><small>졸업 유예 ${state.extraWeeks||0}주 · 준비와 응시에도 시간이 흐릅니다.</small>`:''}<details class="mini-details"><summary>응시 기록 ${t.attempts.length}회</summary>${t.attempts.map((a,i)=>`<div class="history-line"><span>${i+1}회차</span><b>${a.score}점 ${a.score>=730?'· 통과':''}</b></div>`).join('')||'<p>아직 응시하지 않았어요.</p>'}</details></section>`;}
function admissionNotes(){return `<details class="card source-notes"><summary>면접 구성과 게임 설정 안내</summary><p>제출 서류·탐구 경험·수학과학 사고·진로와 협업을 살피는 공식 전형의 요소를 참고했습니다. 게임의 문항은 새로 만든 질문입니다.</p><p>3학년 1학기 지원·면접 일정, 올림피아드 수상에 따른 강한 과학기술원 합격 보정, TOEIC 730점 졸업 조건은 이 게임의 설정입니다. 실제 대학별 일정과 전형을 재현한 예측기가 아닙니다.</p><a href="https://adm-u.unist.ac.kr/admission/community/rolling-admissions.do?articleNo=311513&amp;attachNo=594851&amp;mode=download" target="_blank" rel="noopener">UNIST 2027 탐구우수전형 면접 안내 ↗</a><a href="https://ewww.gist.ac.kr/uadm/html/sub03/0301.html?file_id=76657&amp;mode=D&amp;no=217495" target="_blank" rel="noopener">GIST 2027 입학전형 시행계획(안) ↗</a></details>`;}
function future(){if(!state.alive){deathScreen();return;}const p=E.getProfile(state),finished=state.turn>=48,passed=state.toeic.best>=730;
 let admissionBody='';if(state.admissions)admissionBody=admissionResults();else if(!state.applications?.length){admissionBody=state.turn>=32?`<div class="section-title"><h2>대학 원서 접수</h2><small>3학년 1학기</small></div>${applicationForm()}`:`<div class="card empty">대학 원서는 3학년 1학기에 작성해요.<br>그동안의 성적과 연구, 수상과 활동을 정리해두세요.</div>`;}else{admissionBody=`<section class="card application-status"><div class="eyebrow">APPLICATION IN PROGRESS</div><h2>${state.admissionStage==='interview'?'면접이 진행 중이에요':state.admissionStage==='awaiting_results'?'면접을 마치고 결과를 기다려요':'원서를 제출했어요'}</h2><p>${esc(applicationNames())}</p><div class="admission-steps"><span class="done">원서 제출</span><span class="${state.admissionStage==='interview'?'current':state.admissionStage==='awaiting_results'?'done':''}">전공·연구 면접</span><span>합격 발표</span></div><small>3학년 1학기 동안 학교생활을 이어가면 면접과 발표가 찾아옵니다.</small></section>`;}
 shell(`${heading(finished?'MY ENDING':'THE NEXT CHAPTER',finished?(passed?'우리의 3년, 그리고 시작.':'아직 남은 한 가지, 졸업 영어.'): '대학까지 이어지는 나의 이야기.',finished?(passed?'졸업 조건을 충족했어. 다음 페이지로 나아갈 시간.':'학교생활은 마쳤지만 TOEIC 730점 기준을 아직 충족하지 못했어.'):'3학년 1학기 원서와 면접, 그리고 졸업까지.',finished?(passed?'GRADUATED':'GRADUATION DEFERRED'):'ADMISSIONS & TOEIC')}${finished?`<section class="graduation ${passed?'':'deferred'}"><div class="eyebrow">${esc(state.name)}의 ${passed?'졸업 앨범':'마지막 준비'}</div><h2>${passed?esc(p.strength):'졸업 유예 · TOEIC 재도전'}</h2><p>${passed?esc(p.ending):'대학 전형 결과와 별개로, TOEIC 730점 기준을 충족해야 졸업할 수 있어.'}<br>누적 평점 ${p.gpa.toFixed(2)} / 4.3 · 연구 역량 ${Math.round(state.stats.research)}</p></section>`:timeline()}${toeicPanel()}${admissionBody}${awardsPanel()}${admissionNotes()}${finished?'<button class="secondary" data-do="new" style="margin-top:22px">새로운 3년을 살아보기</button>':''}`);}
function deathScreen(){const p=E.getProfile(state);shell(`${heading('THE LAST PAGE','여기서 멈춘 학교생활.','응급실에서 치료를 받았지만, 이번 삶은 끝을 맞았어.','STORY ENDED')}<section class="ending-card"><div class="ending-star">✧</div><h2>${esc(state.name)}의 이야기는<br>이곳에 남아 있어.</h2><p>함께 보낸 시간과 노력했던 순간들은 기록으로 남았어.<br>새로운 학교생활에서는 다른 선택을 해볼 수 있어.</p><div class="ending-stats"><span>${state.turn}주간의 기록</span><span>평점 ${p.gpa.toFixed(2)}</span><span>수상 ${state.awards.length}회</span></div><button class="primary" data-do="new">새로운 이야기 시작하기 ${icon('arrow')}</button></section><section class="card journal" style="margin-top:22px"><h3>마지막 기록</h3>${recentLog(6)}</section>`);}

function admissionResults(){const list=Array.isArray(state.admissions)?state.admissions:state.admissions?.results||[],graduated=state.ending==='graduated';return `<div class="section-title" style="margin-top:24px"><h2>대학 전형 결과</h2><small>게임 속 가상 결과</small></div>${list.map(r=>`<div class="card result"><div><h3>${esc(r.name||clubName(E.universities,r.id))}</h3><p>${esc(r.reason||'제출한 활동과 면접 결과를 함께 평가했습니다.')}</p>${r.accepted?`<small>${graduated?'졸업 조건 충족 · 진학 가능':'졸업 조건을 충족해야 진학할 수 있어요.'}</small>`:''}</div><span class="${r.accepted?'accepted':'rejected'}">${r.accepted?'합격':'불합격'}</span></div>`).join('')}${!list.some(r=>r.accepted)?'<p class="notice">이번 지원에서 합격 소식을 받지 못했어요. 졸업 후 새로운 진로와 다음 도전을 준비하는 결말로 이어집니다.</p>':''}`;}

function render(){if(!state)setup();else({home,grades,clubs,journal,future}[view]||home)();renderModal();}
function renderModal(){const root=$('#modal-root');root.innerHTML='';$('#app').inert=false;document.body.style.overflow='';if(!state||!state.alive)return;const p=E.getPhase(state);let html='';if(state.pendingEvent){const e=state.pendingEvent;html=`<div class="eyebrow">A MOMENT TO CHOOSE</div><h2 id="modal-title">${esc(e.title)}</h2><p>${esc(e.description)}</p><div class="choices ${e.choices.length>6?'many-choices':''}">${e.choices.map((c,i)=>`<button class="choice" data-choice="${i}"><strong>${esc(c.label)}</strong><small>${esc(c.description||'')}</small></button>`).join('')}</div>`;}else if(p.needsApplications){html=`<div class="eyebrow">A NEW CHAPTER</div><h2 id="modal-title">3학년 1학기,<br>대학 원서를 써보자.</h2><p>지금까지 쌓은 성적과 활동을 바탕으로 지원할 대학을 1~3곳 선택해요. 원서 제출 후 전공·연구 면접이 이어집니다.</p>${applicationForm()}`;}else if(p.needsElectives){html=`<div class="eyebrow">CHOOSE YOUR DIRECTION</div><h2 id="modal-title">2학년 2학기,<br>나의 분야를 선택할 시간.</h2><p>앞으로 배울 선택과목 2개를 골라주세요. 관심 분야와 동아리 경험을 함께 생각해봐도 좋아요. 과목명은 게임용 예시입니다.</p><div class="elective-grid">${E.electives.map(e=>`<label class="check-card"><input type="checkbox" name="elective" value="${e.id}">${esc(e.name)}</label>`).join('')}</div><button class="primary" data-do="electives">선택과목 2개 확정하기</button>`;}else if(semesterNotice){const g=semesterNotice;html=`<div class="eyebrow">ONE CHAPTER COMPLETE</div><h2 id="modal-title">${g.year}학년 ${g.semester}학기를 마쳤어.</h2><p>바쁘게 지나간 한 학기, 너의 노력이 기록되었어.</p><div class="summary-cards" style="grid-template-columns:1fr 1fr"><div class="card summary-card"><small>이번 학기 평점</small><strong>${g.gpa.toFixed(2)}</strong></div><div class="card summary-card"><small>이수 학점</small><strong>${g.earnedCredits ?? g.credits}</strong></div></div><p>과목별 성적은 성적표 탭에서 볼 수 있어요.</p><button class="primary" data-do="dismiss">${state.turn>=48?'졸업 조건 확인하기':'다음 이야기로'} ${icon('arrow')}</button>`;}if(html){$('#app').inert=true;document.body.style.overflow='hidden';root.innerHTML=`<div class="overlay"><section class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">${html}</section></div>`;root.querySelectorAll('[data-choice]').forEach(b=>b.onclick=()=>attempt(()=>{const r=E.chooseEvent(state,Number(b.dataset.choice));persist();render();if(r?.messages?.length)toast(r.messages.join(' '));}));root.querySelectorAll('[data-do]').forEach(b=>b.onclick=()=>dispatch(b.dataset.do));root.querySelectorAll('input[name="elective"]').forEach(i=>i.onchange=()=>{if(root.querySelectorAll('input:checked').length>2){i.checked=false;toast('선택과목은 2개까지 고를 수 있어요.');}});root.querySelectorAll('input[name="university"]').forEach(i=>i.onchange=()=>{if(root.querySelectorAll('input[name="university"]:checked').length>3){i.checked=false;toast('대학은 최대 3곳까지 지원할 수 있어요.');}});setTimeout(()=>root.querySelector('button,input')?.focus(),0);}}
function attempt(fn){try{fn();}catch(e){toast(e.message||'선택을 다시 확인해주세요.');}}
function bind(){$('[data-do="start"]')?.addEventListener('click',()=>dispatch('start'));document.querySelectorAll('.layout [data-do]:not([data-do="start"]),.sidebar [data-do]').forEach(b=>b.onclick=()=>dispatch(b.dataset.do));document.querySelectorAll('[data-nav]').forEach(b=>b.onclick=()=>{view=b.dataset.nav;render();window.scrollTo({top:0,behavior:'instant'});});document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{action=b.dataset.action;render();});document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;render();});document.querySelectorAll('input[name="university"]').forEach(i=>i.onchange=()=>{if(document.querySelectorAll('input[name="university"]:checked').length>3){i.checked=false;toast('대학은 최대 3곳까지 지원할 수 있어요.');}});}
function dispatch(what){attempt(()=>{if(what==='reroll'){const name=$('#student-name').value,ac=$('#academic-club').value,act=$('#activity-club').value;draft=E.create(name||'새로운 학생');render();$('#academic-club').value=ac;$('#activity-club').value=act;return;}if(what==='start'){draft.name=$('#student-name').value.trim()||'새로운 학생';E.setClubs(draft,$('#academic-club').value,$('#activity-club').value);state=draft;view='home';persist();render();window.scrollTo({top:0,behavior:'instant'});return;}if(what==='new'){if(state&&!confirm('현재 진행을 지우고 새로운 학교생활을 시작할까요?'))return;state=null;draft=E.create('새로운 학생');view='home';action='study';mode='normal';semesterNotice=null;try{localStorage.removeItem(KEY);}catch(e){}render();window.scrollTo({top:0,behavior:'instant'});return;}if(what==='advance'){const result=E.advance(state,action,mode);mode='normal';if(result.semesterResult)semesterNotice=result.semesterResult;persist();render();if(result.messages?.length)toast(result.messages.slice(0,2).join(' '));return;}if(what==='electives'){const ids=[...document.querySelectorAll('input[name="elective"]:checked')].map(i=>i.value);if(ids.length!==2){toast('선택과목을 정확히 2개 골라주세요.');return;}E.chooseElectives(state,ids);persist();render();return;}if(what==='dismiss'){semesterNotice=null;if(state.turn>=48)view='future';render();return;}if(what==='retake-toeic'||what==='prepare-toeic'){const r=what==='retake-toeic'?E.takeToeic(state):E.prepareToeic(state);persist();render();if(r?.messages?.length)toast(r.messages.join(' '));return;}if(what==='apply'){const scope=$('.modal')||document;const ids=[...scope.querySelectorAll('input[name="university"]:checked')].map(i=>i.value);if(!ids.length){toast('지원할 대학을 1~3곳 선택해주세요.');return;}E.applyUniversities(state,ids);persist();render();return;}});}
document.addEventListener('keydown',e=>{const modal=$('.modal');if(!modal||e.key!=='Tab')return;const targets=[...modal.querySelectorAll('button,input,select,[tabindex="0"]')].filter(x=>!x.disabled);const first=targets[0],last=targets.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}});
render();
})();
